     1	import { isIsoUtc } from "../lib/datetime.ts";
     2	import { ResponseShapeError } from "./errors.ts";
     3	import {
     4	  SESSION_STATUSES,
     5	  SESSION_TYPES,
     6	  VISIBILITIES,
     7	  type CoachSummary,
     8	  type CoachesResponse,
     9	  type LocationSummary,
    10	  type SessionDetails,
    11	  type SessionSummary,
    12	  type SessionsResponse,
    13	} from "./types.ts";
    14	
    15	// Строгая проверка формы ответа. Все функции бросают ResponseShapeError;
    16	// лишние поля игнорируются, неизвестный enum и невалидная дата = malformed.
    17	
    18	type Obj = Record<string, unknown>;
    19	
    20	function fail(path: string, expected: string, status?: number): never {
    21	  throw new ResponseShapeError(`Unexpected response shape at ${path}: expected ${expected}`, status);
    22	}
    23	
    24	function obj(value: unknown, path: string): Obj {
    25	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    26	    return fail(path, "object");
    27	  }
    28	  return value as Obj;
    29	}
    30	
    31	function str(value: unknown, path: string): string {
    32	  return typeof value === "string" ? value : fail(path, "string");
    33	}
    34	
    35	function num(value: unknown, path: string): number {
    36	  return typeof value === "number" && Number.isFinite(value) ? value : fail(path, "number");
    37	}
    38	
    39	function nullableStr(value: unknown, path: string): string | null {
    40	  return value === null ? null : str(value, path);
    41	}
    42	
    43	function iso(value: unknown, path: string): string {
    44	  const s = str(value, path);
    45	  return isIsoUtc(s) ? s : fail(path, "ISO 8601 UTC date");
    46	}
    47	
    48	function oneOf<T extends string>(value: unknown, allowed: readonly T[], path: string): T {
    49	  const s = str(value, path);
    50	  return (allowed as readonly string[]).includes(s) ? (s as T) : fail(path, allowed.join(" | "));
    51	}
    52	
    53	function array(value: unknown, path: string): unknown[] {
    54	  return Array.isArray(value) ? value : fail(path, "array");
    55	}
    56	
    57	export function parseCoach(value: unknown, path = "coach"): CoachSummary {
    58	  const o = obj(value, path);
    59	  return {
    60	    id: str(o.id, `${path}.id`),
    61	    name: str(o.name, `${path}.name`),
    62	    email: str(o.email, `${path}.email`),
    63	  };
    64	}
    65	
    66	function parseLocation(value: unknown, path: string): LocationSummary {
    67	  const o = obj(value, path);
    68	  return {
    69	    name: str(o.name, `${path}.name`),
    70	    address: str(o.address, `${path}.address`),
    71	  };
    72	}
