   136	  if (typeof value !== "object" || value === null) return null;
   137	  const error = (value as Obj).error;
   138	  if (typeof error !== "object" || error === null) return null;
   139	  const e = error as Obj;
   140	  if (typeof e.code !== "string" || typeof e.message !== "string") return null;
   141	  let fieldErrors: Record<string, string> | undefined;
   142	  if (typeof e.fieldErrors === "object" && e.fieldErrors !== null && !Array.isArray(e.fieldErrors)) {
