    16	/** Отмена не ошибка данных: отдельный признак `cancelled`. */
    17	export type ApiResult<T> =
    18	  | { ok: true; data: T }
    19	  | { ok: false; cancelled: false; error: ClientError }
    20	  | { ok: false; cancelled: true };
    21	
