    30	
    31	interface RequestSpec<T> {
    32	  method: "GET" | "POST";
    33	  path: string;
    34	  expectedStatus: number;
    35	  parse: (json: unknown) => T;
    36	  body?: unknown;
    37	  signal?: AbortSignal;
    38	}
    39	
    40	function failure(error: ClientError): ApiResult<never> {
    41	  return { ok: false, cancelled: false, error };
    42	}
    43	
    44	// Единственное место вызова fetch.
    45	async function request<T>(spec: RequestSpec<T>): Promise<ApiResult<T>> {
    46	  const { signal } = spec;
    47	  const headers: Record<string, string> = { Accept: "application/json" };
    48	  const init: RequestInit = { method: spec.method, headers, signal };
    49	  if (spec.body !== undefined) {
    50	    headers["Content-Type"] = "application/json";
    51	    init.body = JSON.stringify(spec.body);
    52	  }
    53	
    54	  let response: Response;
    55	  try {
    56	    response = await fetch(spec.path, init);
    57	  } catch {
    58	    return signal?.aborted ? { ok: false, cancelled: true } : failure(new NetworkError());
    59	  }
    60	
    61	  let text: string;
    62	  try {
    63	    text = await response.text();
    64	  } catch {
    65	    return signal?.aborted ? { ok: false, cancelled: true } : failure(new NetworkError());
    66	  }
    67	  if (signal?.aborted) return { ok: false, cancelled: true };
    68	
    69	  let json: unknown;
    70	  let jsonOk = true;
    71	  try {
    72	    json = JSON.parse(text);
    73	  } catch {
    74	    jsonOk = false;
    75	  }
    76	
    77	  if (!response.ok) {
    78	    const body = jsonOk ? parseErrorBody(json) : null;
    79	    if (body) {
    80	      return failure(new ApiError(response.status, body.code, body.message, body.fieldErrors));
    81	    }
    82	    return failure(new ResponseShapeError("Error response has no contract body", response.status));
    83	  }
    84	
    85	  if (response.status !== spec.expectedStatus) {
    86	    return failure(
    87	      new ResponseShapeError(`Unexpected success status ${response.status}`, response.status),
    88	    );
    89	  }
    90	  if (!jsonOk) {
    91	    return failure(new ResponseShapeError("Response body is not JSON", response.status));
    92	  }
    93	  try {
    94	    return { ok: true, data: spec.parse(json) };
    95	  } catch (error) {
    96	    if (error instanceof ResponseShapeError) {
    97	      return failure(new ResponseShapeError(error.message, response.status));
    98	    }
    99	    throw error;
   100	  }
   101	}
