    17	export function navigate(to: string, options: NavigateOptions = {}): void {
    18	  if (options.replace) {
    19	    window.history.replaceState(options.state ?? null, "", to);
    20	  } else {
    21	    window.history.pushState(options.state ?? null, "", to);
