    25	
    26	/** Состояние текущей записи истории (флаг «из приложения / из списка» задаёт вызывающий код). */
    27	export function readHistoryState(): unknown {
    28	  return window.history.state;
    29	}
    30	
    31	function subscribe(onChange: () => void): () => void {
    32	  window.addEventListener("popstate", onChange);
    33	  window.addEventListener(NAVIGATE_EVENT, onChange);
    34	  return () => {
    35	    window.removeEventListener("popstate", onChange);
    36	    window.removeEventListener(NAVIGATE_EVENT, onChange);
    37	  };
    38	}
    39	
    40	function getSnapshot(): string {
    41	  return window.location.pathname + window.location.search;
    42	}
    43	
    44	/** Текущие path и search с подпиской на popstate и собственные навигации. */
    45	export function useLocation(): RouterLocation {
    46	  const snapshot = useSyncExternalStore(subscribe, getSnapshot);
    47	  return useMemo(() => {
    48	    const i = snapshot.indexOf("?");
    49	    return i === -1
    50	      ? { pathname: snapshot, search: "" }
    51	      : { pathname: snapshot.slice(0, i), search: snapshot.slice(i) };
    52	  }, [snapshot]);
    53	}
    54	
    55	function normalizePath(pathname: string): string {
    56	  return pathname.length > 1 && pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;
    57	}
    58	
    59	/** Сопоставление пути с шаблоном вида `/sessions/:id`. `null`, если путь не подходит. */
    60	export function matchPath(pattern: string, pathname: string): Record<string, string> | null {
    61	  const want = normalizePath(pattern).split("/");
    62	  const have = normalizePath(pathname).split("/");
    63	  if (want.length !== have.length) return null;
    64	  const params: Record<string, string> = {};
    65	  for (let i = 0; i < want.length; i += 1) {
    66	    const w = want[i];
    67	    const h = have[i];
    68	    if (w.startsWith(":")) {
    69	      if (h === "") return null;
    70	      try {
    71	        params[w.slice(1)] = decodeURIComponent(h);
    72	      } catch {
    73	        return null;
    74	      }
    75	    } else if (w !== h) {
    76	      return null;
    77	    }
    78	  }
    79	  return params;
    80	}
