    86	/**
    87	 * Возвращает новый search (`?a=b` или пустую строку). `null`/`undefined`/`""` удаляют параметр,
    88	 * остальные параметры сохраняются нетронутыми.
    89	 */
    90	export function updateSearch(
    91	  search: string,
    92	  updates: Record<string, string | null | undefined>,
    93	): string {
    94	  const params = new URLSearchParams(search);
    95	  for (const [name, value] of Object.entries(updates)) {
    96	    if (value === null || value === undefined || value === "") {
    97	      params.delete(name);
    98	    } else {
    99	      params.set(name, value);
   100	    }
   101	  }
   102	  const next = params.toString();
   103	  return next ? `?${next}` : "";
   104	}
   105	
   106	/** Неизвестный путь -> `replace` на `fallback` с сохранением search. */
   107	export function useRedirectUnknown(knownPatterns: readonly string[], fallback: string): void {
   108	  const { pathname, search } = useLocation();
   109	  const known = knownPatterns.some((pattern) => matchPath(pattern, pathname) !== null);
   110	  useEffect(() => {
   111	    if (!known) navigate(`${fallback}${search}`, { replace: true });
   112	  }, [known, fallback, search]);
   113	}

