   114	 */
   115	export function localToIsoUtc(date: string, time: string): LocalToIsoResult {
   116	  const d = LOCAL_DATE_PATTERN.exec(date);
   117	  const t = LOCAL_TIME_PATTERN.exec(time);
   118	  if (!d) return { ok: false, reason: "invalid-date" };
   119	  if (!t) return { ok: false, reason: "invalid-time" };
   120	  const [year, month, day] = [Number(d[1]), Number(d[2]), Number(d[3])];
   121	  const [hour, minute] = [Number(t[1]), Number(t[2])];
   122	
   123	  // Календарная проверка независимо от пояса (30 февраля и т. п.).
   124	  const utc = new Date(Date.UTC(year, month - 1, day));
   125	  if (
   126	    utc.getUTCFullYear() !== year ||
   127	    utc.getUTCMonth() !== month - 1 ||
   128	    utc.getUTCDate() !== day
   129	  ) {
   130	    return { ok: false, reason: "invalid-date" };
   131	  }
   132	  if (hour > 23 || minute > 59) return { ok: false, reason: "invalid-time" };
   133	
   134	  const local = new Date(year, month - 1, day, hour, minute, 0, 0);
   135	  if (Number.isNaN(local.getTime())) return { ok: false, reason: "invalid-date" };
   136	  if (
   137	    local.getFullYear() !== year ||
   138	    local.getMonth() !== month - 1 ||
   139	    local.getDate() !== day ||
   140	    local.getHours() !== hour ||
   141	    local.getMinutes() !== minute
   142	  ) {
   143	    return { ok: false, reason: "nonexistent-time" };
   144	  }
   145	  return { ok: true, iso: formatIsoUtc(local.getTime()) };
