    15	export type ScenarioName = (typeof SCENARIO_NAMES)[number];
    16	export type ScenarioSource = "url" | "env" | "default";
    17	
    18	export interface ScenarioSelection {
    19	  name: ScenarioName;
    20	  source: ScenarioSource;
    21	}
    22	
    23	export function isScenarioName(value: unknown): value is ScenarioName {
    24	  return typeof value === "string" && (SCENARIO_NAMES as readonly string[]).includes(value);
    25	}
    26	
    27	/**
    28	 * Приоритет: ?scenario= в URL, затем VITE_MOCK_SCENARIO, затем normal.
    29	 * Невалидное имя -> console.warn и откат на следующий источник.
    30	 */
    31	export function resolveScenario(search: string, envValue: unknown): ScenarioSelection {
    32	  const fromUrl = new URLSearchParams(search).get("scenario");
    33	  const candidates: [ScenarioSource, string | null][] = [
    34	    ["url", fromUrl],
    35	    ["env", typeof envValue === "string" && envValue !== "" ? envValue : null],
    36	  ];
    37	  for (const [source, value] of candidates) {
    38	    if (value === null) continue;
    39	    if (isScenarioName(value)) return { name: value, source };
    40	    console.warn(
    41	      `[mock] Unknown scenario "${value}" from ${source}. Allowed: ${SCENARIO_NAMES.join(", ")}.`,
    42	    );
    43	  }
