    28	function loadFixtures(now: number): SessionDetails[] {
    29	  const delta = computeDelta(now);
    30	  const byId = new Map<string, SessionDetails>();
    31	  for (const raw of rawDetails) {
    32	    const parsed = parseSessionDetails(shiftTimestamps(raw, delta));
    33	    byId.set(parsed.id, parsed);
    34	  }
    35	  return rawOrder.map((id) => {
    36	    const found = byId.get(id);
    37	    if (!found) throw new Error(`Missing details fixture for ${id}`);
    38	    return found;
    39	  });
    40	}
    41	
    42	/** Сброс хранилища к стартовому состоянию (вызывается при старте мока и между тестами). */
    43	export function resetStore(options: ResetOptions = {}): void {
    44	  sessions = options.empty ? [] : loadFixtures(options.now ?? currentTime());
    45	  const numbers = sessions.map((s) => Number(s.id.replace(/^ses_/, ""))).filter(Number.isFinite);
    46	  nextNumber = (numbers.length > 0 ? Math.max(...numbers) : 100) + 1;
    47	}
