    78	/** Добавляет сессию в конец списка и возвращает её; id генерирует хранилище. */
    79	export function addSession(
    80	  draft: Omit<SessionDetails, "id" | "createdAt" | "updatedAt">,
    81	  now: number,
    82	): SessionDetails {
    83	  const stamp = formatIsoUtc(now);
